var wg sync.WaitGroup
for _, shard := range shards {
    wg.Add(1)                      // before the goroutine starts
    go func(s Shard) {
        defer wg.Done()            // runs even if the worker panics past recover
        process(s)
    }(shard)                       // explicit parameter: Go < 1.22 loop capture
}
wg.Wait()                          // one-shot fan-in

