gates := make([]chan struct{}, steps)       // one release gate per phase
for i := range gates { gates[i] = make(chan struct{}) }
arrived := make(chan struct{}, n)
go func() {                              // gatekeeper: one generation at a time
    for i := range gates {
        for j := 0; j < n; j++ { <-arrived }  // wait for every party
        close(gates[i])                        // broadcast the release
    }
}()
